});

frappe.ui.form.on("Booking Measurement", {
    from_month: function(frm) { generate_periods(frm); },
    from_year: function(frm) { generate_periods(frm); },
    to_month: function(frm) { generate_periods(frm); },
    to_year: function(frm) { generate_periods(frm); },
    source_type: function(frm) { generate_periods(frm); }
});

function generate_periods(frm) {
    // حساب عدد الأشهر وتعيينه في payment_cycle
    calculate_payment_cycle(frm);

    if (!frm.doc.agency_name || !frm.doc.from_month || !frm.doc.from_year ||
        !frm.doc.to_month || !frm.doc.to_year || !frm.doc.source_type) {
        return;
    }

    frappe.call({
        method: "generate_booking_measurement_periods",
        args: {
            agency_name: frm.doc.agency_name,
            from_month: frm.doc.from_month,
            from_year: frm.doc.from_year,
            to_month: frm.doc.to_month,
            to_year: frm.doc.to_year,
            source_type: frm.doc.source_type
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                frm.clear_table("table_leve");

                var sum_air = 0;
                var sum_ndc = 0;
                var sum_total = 0;

                r.message.forEach(function(row) {
                    var child = frm.add_child("table_leve");
                    child.month = String(row.month);
                    child.year = String(row.year);
                    
                    child.air = flt(row.air);
                    child.ndc = flt(row.ndc);
                    child.total = flt(row.total);

                    sum_air += child.air;
                    sum_ndc += child.ndc;
                    sum_total += child.total;
                });

                // إضافة سطر المجموع النهائي
                var summary_row = frm.add_child("table_leve");
                summary_row.month = "Total";
                summary_row.air = sum_air;
                summary_row.ndc = sum_ndc;
                summary_row.total = sum_total;

                frm.refresh_field("table_leve");
            }
        }
    });
}

function calculate_payment_cycle(frm) {
    if (!frm.doc.from_month || !frm.doc.from_year || !frm.doc.to_month || !frm.doc.to_year) {
        return;
    }

    // خيارات قائمة Select الكاملة
    const months = [
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    ];

    // جلب الترتيب الرقمي للشهر (من 1 إلى 12)
    let f_month = months.indexOf(frm.doc.from_month) + 1;
    let t_month = months.indexOf(frm.doc.to_month) + 1;
    let f_year = parseInt(frm.doc.from_year, 10);
    let t_year = parseInt(frm.doc.to_year, 10);

    if (f_month > 0 && t_month > 0 && f_year && t_year) {
        // حساب مجموع الأشهر للفترة كاملة
        let total_months = ((t_year - f_year) * 12) + (t_month - f_month) + 1;
        
        frm.set_value("payment_cycle", total_months > 0 ? total_months : 0);
    }
}

frappe.ui.form.on('Payment Tracking', {
    refresh: function(frm) {
        frm.set_query('agency_contract', function() {
            return {};
        });
        frm.set_query('booking_measurement', function() {
            return {};
        });
    },
    agency_contract: function(frm) {
        if (frm.doc.agency_contract) {
            frappe.db.get_doc('Agency Contract', frm.doc.agency_contract)
            .then(function(contract) {
                frm.set_value('agency_name', contract.agency_name);
                frm.set_value('account_manager', contract.account_manager);
            });
        }
    },
    booking_measurement: function(frm) {
        if (frm.doc.booking_measurement) {
            frappe.db.get_doc('Booking Measurement', frm.doc.booking_measurement)
            .then(function(booking) {
                frm.set_value('agency_name', booking.agency_name);
                frm.set_value('account_manager', booking.account_manager);
                frm.set_value('agency_contract', booking.agency_contract);
                frm.set_value('sc_code', booking.sc_code);

                var period = (booking.from_month || '') + ' ' + (booking.from_year || '') +
                             ' --> ' + (booking.to_month || '') + ' ' + (booking.to_year || '');
                frm.set_value('measure_period', period);

                frm.set_value('payment_amount', booking.total);

                if (booking.to_month && booking.to_year) {
                    var months = ['January', 'February', 'March', 'April', 'May', 'June',
                                  'July', 'August', 'September', 'October', 'November', 'December'];

                    var to_month_index = months.indexOf(booking.to_month);

                    if (to_month_index !== -1) {
                        var new_month_index = (to_month_index + 3) % 12;
                        var year_offset = Math.floor((to_month_index + 3) / 12);
                        var new_year = parseInt(booking.to_year) + year_offset;

                        frm.set_value('payment_date', months[new_month_index] + ' ' + new_year);
                    }
                }
            });
        }
    }
});

