frappe.ui.form.on('Booking Measurement', {
    agency_contract: function(frm) {
        if (!frm.doc.agency_contract) {
            frm.clear_table('contract_measurements');
            frm.refresh_field('contract_measurements');
            return;
        }

        frappe.db.get_doc('Agency Contract', frm.doc.agency_contract)
            .then(contract_doc => {
                // 1. تفريغ الجدول في Booking Measurement
                frm.clear_table('contract_measurements');

                // 2. قراءة البيانات من حقل tiers في العقد المصدر
                if (contract_doc.tiers && contract_doc.tiers.length > 0) {
                    contract_doc.tiers.forEach(row => {
                        let child = frm.add_child('contract_measurements');
                        
                        child.tier_type = row.tier_type;
                        child.from = row.from;
                        child.to = row.to;
                        child.rate = row.rate;
