function generate_periods(frm) {
    calculate_payment_cycle(frm);

    if ((!frm.doc.sc_code && !frm.doc.agency_name) ||
        !frm.doc.from_month || !frm.doc.from_year ||
        !frm.doc.to_month || !frm.doc.to_year || !frm.doc.source_type) {
        return;
    }

    frappe.call({
        method: "generate_booking_measurement_periods",
        args: {
            sc_code: frm.doc.sc_code,
            agency_name: frm.doc.agency_name,
            from_month: frm.doc.from_month,
            from_year: frm.doc.from_year,
            to_month: frm.doc.to_month,
            to_year: frm.doc.to_year,
            source_type: frm.doc.source_type
        },
        callback: function(r) {
            if (r.message && r.message.length > 0) {
                frm.clear_table("table_leve");

                var sum_air = 0;
                var sum_ndc = 0;
                var sum_total = 0;

                r.message.forEach(function(row) {
                    var child = frm.add_child("table_leve");
                    child.month = String(row.month);
                    child.year = String(row.year);

                    child.air = flt(row.air);
                    child.ndc = flt(row.ndc);
                    child.total = flt(row.total);

                    sum_air += child.air;
                    sum_ndc += child.ndc;
                    sum_total += child.total;
                });

                var summary_row = frm.add_child("table_leve");
                summary_row.month = "Total";
                summary_row.year = "";
                summary_row.air = sum_air;
                summary_row.ndc = sum_ndc;
                summary_row.total = sum_total;

                frm.refresh_field("table_leve");
                calculate_incentive_totals(frm);
            }
        }
    });
}

function calculate_payment_cycle(frm) {
    if (!frm.doc.from_month || !frm.doc.from_year || !frm.doc.to_month || !frm.doc.to_year) {
        return;
    }

    const months = [
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    ];

    let f_month = months.indexOf(frm.doc.from_month) + 1;
    let t_month = months.indexOf(frm.doc.to_month) + 1;
    let f_year = parseInt(frm.doc.from_year, 10);
    let t_year = parseInt(frm.doc.to_year, 10);

    if (f_month > 0 && t_month > 0 && f_year && t_year) {
        let total_months = ((t_year - f_year) * 12) + (t_month - f_month) + 1;
        frm.set_value("payment_cycle", total_months > 0 ? total_months : 0);
    }
}

function calculate_incentive_totals(frm) {
    var sum_air = 0;
    var sum_ndc = 0;
    var sum_total = 0;

    (frm.doc.table_leve || []).forEach(function(row) {
        if (row.month !== "Total") {
            sum_air += flt(row.air);
            sum_ndc += flt(row.ndc);
            sum_total += flt(row.total);
        }
    });

    var air_rate = 0;
    var ndc_rate = 0;

    (frm.doc.contract_measurements || []).forEach(function(row) {
        var from_val = flt(row.from);
        var to_val = flt(row.to);
        var rate = flt(row.rate);
        var type = (row.tier_type || "").toUpperCase();

        if ((!type || type === "AIR") && sum_air >= from_val && sum_air <= to_val) {
            air_rate = rate;
        }

        if ((!type || type === "NDC") && sum_ndc >= from_val && sum_ndc <= to_val) {
            ndc_rate = rate;
        }
    });

    var calc_total_air = sum_air * air_rate;
    var calc_total_ndc = sum_ndc * ndc_rate;
    var calc_total_segments = calc_total_air + calc_total_ndc;
    var based_incentives = calc_total_segments;

    var target_segments = flt(frm.doc.segments);
    var shortfall_rate = flt(frm.doc.shortfall_rate);
    var shortfall = 0;

    if (frm.doc.period === "Annual" && sum_total < target_segments) {
        shortfall = (target_segments - sum_total) * shortfall_rate;
    } else {
        shortfall = 0;
    }

    var ek_a_option = flt(frm.doc.ek_a_option);
    var upfront_val = flt(frm.doc.upfront);
    
    // قيم الحقول الجديدة
    var productivity_amount = flt(frm.doc.productivity_amount);
    var loyalty_bonus = flt(frm.doc.loyalty_bonus);
    var line_of_credit = flt(frm.doc.line_of_credit);

    // معادلة الحساب المعدلة
    var subtotal_usd = based_incentives - shortfall - ek_a_option + upfront_val + productivity_amount + loyalty_bonus + line_of_credit;

    var paid = flt(frm.doc.paid);
    var total = subtotal_usd - paid;

    frm.set_value("total_air", calc_total_air);
    frm.set_value("total_ndc", calc_total_ndc);
    frm.set_value("total_segments", calc_total_segments);
    frm.set_value("based_incentives", based_incentives);
    frm.set_value("shortfall", shortfall);
    frm.set_value("subtotal_usd", subtotal_usd);
    frm.set_value("total", total);
}

