function calculate_payment_date(frm) {
    if (!frm.doc.to_month || !frm.doc.to_year) return;

    const months = [
        "January", "February", "March", "April", "May", "June",
        "July", "August", "September", "October", "November", "December"
    ];

    let to_month_index = months.indexOf(frm.doc.to_month);
    if (to_month_index === -1) return;

    let new_month_index = (to_month_index + 3) % 12;
    let year_offset = Math.floor((to_month_index + 3) / 12);
    let new_year = parseInt(frm.doc.to_year, 10) + year_offset;

    frm.set_value("payment_date", months[new_month_index] + " " + new_year);
}

